func TestDiffReportsChangedRuleVersionOnly(t *testing.T) {
	artifact := testArtifact("Vault", testHashA)
	before := buildTestReport(testID1, artifact, []ReportRule{
		testRule("r1", "static", "high", "inv", false, "1.0.0", StatusPass),
