	}
}

func TestDiffReportsStatusChange(t *testing.T) {
	artifact := testArtifact("Vault", testHashA)
	for _, tc := range []struct {
		from, to string
	}{
		{StatusUnchecked, StatusPass},
		{StatusPass, StatusUnchecked},
